css:
[data-bz-node="fg-text"] { display: flex; flex-direction: column; gap: 18px; }
[data-bz-node="fg-text"] > * { margin: 0; }
[data-bz-node="fg-row"]:not(:has([data-bz-node="fg-text"] :is(h2, p, a))) > [data-bz-node="fg-text"] { display: none; }
[data-bz-node="fg-row"]:not(:has([data-bz-node="fg-text"] :is(h2, p, a))) > [data-bz-node="fg-grid-col"] { grid-column: 1 / -1; }
[data-bz-node="fg-grid"] { gap: 16px; }
[data-bz-node^="fgitem"] { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius-card); padding: 10px; display: flex; flex-direction: column; gap: 10px; transition: box-shadow var(--hcm-dur) var(--hcm-ease); }
[data-bz-node^="fgitem"]:hover { box-shadow: var(--hcm-shadow); }
[data-bz-node^="fg-img"] img { width: 100%; height: auto; border-radius: var(--radius-input); }
[data-bz-node^="fg-img"] a { display: block; cursor: zoom-in; }
[data-bz-node^="fg-img"] a[href$=".pdf"] { cursor: pointer; }
[data-bz-node^="fg-dl"] .bz-btns { margin: 0; }
[data-bz-node^="fg-dl"] .bz-btn { width: 100%; font-size: 15px; padding: 10px 16px; letter-spacing: .08em; }
[data-bz-node^="fgitem"] { justify-content: space-between; }
[data-bz-node="fg-cta"] .bz-btns { margin: 0; }
@media (max-width: 900px) { [data-bz-node="fg-row"] > .bz-col { grid-column: 1 / -1; } [data-bz-node^="fgitem"] { grid-column: span 6; } }
.hcm-lightbox { position: fixed; inset: 0; z-index: 90; background: rgb(16 32 67 / 88%); display: flex; align-items: center; justify-content: center; padding: clamp(16px, 4vw, 48px); cursor: zoom-out; }
.hcm-lightbox img { max-width: 100%; max-height: 100%; object-fit: contain; border-radius: 4px; box-shadow: 0 20px 60px rgb(0 0 0 / 40%); }
.hcm-lightbox button { all: unset; cursor: pointer; position: absolute; top: 16px; right: 20px; width: 44px; height: 44px; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 32px; line-height: 1; }
.hcm-lightbox button:focus-visible { outline: 2px solid var(--hcm-focus); }

js:
// Lightbox for flyers. Each flyer is an ordinary link to its full-size image, so
// without this script (and on the editing canvas) clicking still opens the image.
(function () {
  function open(link) {
    var img = link.querySelector('img');
    var box = document.createElement('div');
    box.className = 'hcm-lightbox';
    box.setAttribute('role', 'dialog');
    box.setAttribute('aria-modal', 'true');
    box.setAttribute('aria-label', img && img.alt ? img.alt : 'Flyer');
    var big = document.createElement('img');
    big.src = link.href;
    big.alt = img ? img.alt : '';
    var close = document.createElement('button');
    close.type = 'button';
    close.setAttribute('aria-label', 'Close');
    close.textContent = '\u00d7';
    box.appendChild(big);
    box.appendChild(close);
    function shut() { box.remove(); document.removeEventListener('keydown', onKey); link.focus(); }
    function onKey(e) { if (e.key === 'Escape') shut(); }
    box.addEventListener('click', shut);
    document.addEventListener('keydown', onKey);
    document.body.appendChild(box);
    close.focus();
  }
  document.addEventListener('click', function (e) {
    var link = e.target.closest('[data-bz-section="flyer-grid"] [data-bz-node^="fg-img"] a');
    if (!link || !/\.(png|jpe?g|webp|gif)(\?|$)/i.test(link.getAttribute('href') || '')) return;
    e.preventDefault();
    open(link);
  });
})();
